function scheduleFarewell(s, prev, coach, years, up) {
  s.exClub = { name: prev.name, coach, years, up, to: s.club.name };
  s.flags.farewells = (s.flags.farewells ?? 0) + 1;
  const ph = s.phone;
  if (!ph) return;
  ph.due = ph.due.filter((d) => !d.step.startsWith("pozegnanie."));
  ph.inbox = ph.inbox.filter((m) => m.picked !== void 0 || !(m.id.startsWith("pozegnanie.") || m.app === "gym"));
  const n = s.flags.farewells;
  if (n <= 2 || years >= 2) ph.due.push({ step: "pozegnanie.trener", at: ph.tick + 1 });
  if (years >= 2) ph.due.push({ step: "pozegnanie.kumpel", at: ph.tick + 1 });
  if (years >= 3) ph.due.push({ step: "pozegnanie.grupa", at: ph.tick + 2 });
}

