// src/engine/events_fun.ts
var vary3 = (s, arr) => arr[(s.season * 11 + s.age * 5) % arr.length];
var FUN_EVENTS = [
  {
    id: "babcia_rosol",
    title: "Babcia i dieta",
    weight: 4,
    cond: (s) => s.tier >= 0,
    text: (s) => vary3(s, [
      "Tydzie\u0144 przed walk\u0105 babcia stawia przed tob\u0105 talerz roso\u0142u, schabowego i trzy rodzaje ciasta. \u201ETy taki chudy, jak ty si\u0119 bi\u0107 b\u0119dziesz? Jedz, bo ci\u0119 ten drugi przewr\xF3ci\u201D.",
      "Niedzielny obiad u babci. Na stole pierogi w czterech smakach i pi\u0105ty, eksperymentalny. Dietetyk pisze na \u0141apCappie: \u201EMam nadziej\u0119, \u017Ce trzymasz makro\u201D. Babcia pyta, kto to Makro."
    ]),
    choices: () => [
      { label: "Jesz wszystko", desc: "Babci si\u0119 nie odmawia. Babcia zapami\u0119tuje ka\u017Cd\u0105 odmow\u0119 od 1974 roku.", effects: { relations: 2, form: -1, note: "waga skacze, babcia szcz\u0119\u015Bliwa" } },
      { label: "T\u0142umaczysz, czym jest makro", desc: "P\xF3\u0142 godziny wyk\u0142adu o bia\u0142ku. Babcia s\u0142ucha jak kazania, czyli my\u015Bli o czym\u015B innym.", chance: 35, success: { relations: 1, form: 1, note: "babcia robi ci kurczaka na parze" }, fail: { relations: -1, note: "babcia obra\u017Cona do \u015Bwi\u0105t" }, successText: "Babcia s\u0142ucha, kiwa g\u0142ow\u0105 i w \u015Brod\u0119 przynosi ci pude\u0142ko kurczaka z ry\u017Cem. Podpisane d\u0142ugopisem: \u201EMAKRO\u201D. Pod spodem schowany p\u0105czek, \u201Ena wszelki wypadek\u201D.", failText: "Babcia wychodzi do kuchni i stawia garnki tak, \u017Ce s\u0142ycha\u0107 to na ca\u0142ym osiedlu. Mama m\xF3wi, \u017Ce przez ciebie nie b\u0119dzie sernika na \u015Bwi\u0119ta." }
    ]
  },
  {
    id: "sasiad_wiertarka",
    title: "S\u0105siad z wiertark\u0105",
    weight: 3,
    cond: (s) => s.age >= 18,
    text: () => "\u015Arodek ci\u0119\u017Ckiego obozu, rano masz sparingi, a s\u0105siad zza \u015Bciany zaczyna remont. O 23:40 wiertarka udarowa, o 0:15 m\u0142otek. Przez \u015Bcian\u0119: \u201EMusz\u0119 sko\u0144czy\u0107 p\xF3\u0142k\u0119 przed weekendem, k***a, bo \u017Cona mnie zabije\u201D.",
    choices: () => [
      { label: "Idziesz porozmawia\u0107", desc: "Grzecznie, ale stanowczo. W bluzie klubowej, \u017Ceby rozmowa by\u0142a kr\xF3tsza.", chance: 60, success: { form: 1, note: "s\u0105siad przeprasza i przynosi ciasto" }, fail: { media: 1, rep: -1, note: "s\u0105siad nagrywa ci\u0119 telefonem" }, successText: "S\u0105siad okazuje si\u0119 twoim kibicem, przeprasza i zostawia pod drzwiami blach\u0119 szarlotki. P\xF3\u0142ka do dzi\u015B wisi krzywo. \u015Apisz jak dziecko.", failText: "S\u0105siad nagrywa rozmow\u0119 i wrzuca na grup\u0119 osiedlow\u0105: \u201EZAWODNIK MMA GROZI EMERYTOWI\u201D. Nikt nikomu nie grozi\u0142, ale pani z parteru ju\u017C podpisuje petycj\u0119 o twoje wysiedlenie." },
      { label: "Zatyczki i sen", desc: "Nie dasz si\u0119 wyprowadzi\u0107 z r\xF3wnowagi. Wiertarce si\u0119 to uda.", effects: { form: -1, note: "spa\u0142e\u015B cztery godziny" } }
    ]
  },
  {
    id: "tiktok_trend",
    title: "Trend z internetu",
    weight: 4,
    cond: (s) => s.tier >= 1,
    text: (s) => vary3(s, [
      "Klubowy specjalista od medi\xF3w spo\u0142eczno\u015Bciowych, czyli siostrzeniec prezesa, chce, \u017Ceby\u015B nagra\u0142 taniec do modnego trendu. W r\u0119kawicach. \u201EAlgorytm to kocha, ziomek\u201D.",
      "M\u0142odsi koledzy z klubu nagrywaj\u0105 filmik \u201Ezawodnik MMA ocenia pierogi z r\xF3\u017Cnych miast\u201D. Chc\u0105, \u017Ceby\u015B by\u0142 jurorem. Pierogi z jednego miasta s\u0105 z mro\u017Conki, wszyscy o tym wiedz\u0105."
    ]),
    choices: (s) => [
      { label: "Wchodzisz w to", desc: "Raz si\u0119 \u017Cyje. Raz si\u0119 te\u017C ta\u0144czy w r\u0119kawicach.", chance: 55, success: { media: 3, note: "filmik robi rekord twojego profilu" }, fail: { media: 1, rep: -2, note: "internet si\u0119 \u015Bmieje, ale nie z tob\u0105" }, successText: `Filmik ma ${viewsTxt(s, 8)} wy\u015Bwietle\u0144 w dwa dni. W komentarzach: \u201Eta\u0144czy lepiej, ni\u017C si\u0119 bije\u201D, \u201Ebiodra jak wodzirej na weselu\u201D. Trener udaje, \u017Ce nie widzia\u0142, ale po treningu pyta o ten jeden krok.`, failText: "Ruszasz si\u0119 jak szafa na k\xF3\u0142kach w czasie trz\u0119sienia ziemi. Komentarze bezlitosne, a rywal udost\u0119pnia filmik z trzema emotkami p\u0142aczu ze \u015Bmiechu i podpisem \u201Esparing z lod\xF3wk\u0105\u201D." },
      { label: "Odmawiasz", desc: "Jeste\u015B tu, \u017Ceby si\u0119 bi\u0107. Ta\u0144czy\u0107 b\u0119dziesz na weselu kuzyna. Te\u017C \u017Ale, ale bez kamer.", effects: { rep: 1 } }
    ]
  },
  {
    id: "mama_w_hali",
    title: "Mama na trybunach",
    once: true,
    weight: 4,
    cond: (s) => s.tier >= 1 && !!s.proDebut,
    text: () => "Mama po raz pierwszy przychodzi na twoj\u0105 gal\u0119. Przynios\u0142a transparent \u201ESYNKU, NIE DAJ SI\u0118\u201D, kanapki dla ca\u0142ego sektora i termos z herbat\u0105. Ochrona chcia\u0142a jej zabra\u0107 termos. Nie zabra\u0142a.",
    choices: () => [
      { label: "Machasz do niej przed walk\u0105", desc: "Kamera to \u0142apie. Realizator robi zbli\u017Cenie. Mama p\u0142acze, p\xF3\u0142 hali te\u017C.", effects: { relations: 2, media: 2, form: 1, note: "ca\u0142a hala bije brawo mamie" } },
      { label: "Prosisz, \u017Ceby schowa\u0142a transparent", desc: "Skupienie przede wszystkim. Mama chowa transparent i wyjmuje drugi, mniejszy.", effects: { relations: -2, form: 1 } }
    ]
  },
  {
    id: "kot_trenera",
    title: "Kot trenera",
    once: true,
    weight: 3,
    cond: (s) => s.tier >= 0,
    text: () => "Trener przyprowadza na sal\u0119 kota, bo \u201Esam w domu si\u0119 nudzi i sika do but\xF3w\u201D. Kot \u015Bpi na macie do parteru, dok\u0142adnie tam, gdzie macie robi\u0107 drille. Kot ma lepsz\u0105 gard\u0119 ni\u017C po\u0142owa klubu.",
    choices: () => [
      { label: "Trenujecie wok\xF3\u0142 kota", desc: "Kot ma pierwsze\u0144stwo. Kot to w ko\u0144cu trener trenera.", effects: { stats: { iq: 1 }, relations: 1, note: "uczysz si\u0119 kontroli pozycji w ograniczonej przestrzeni" } },
      { label: "Przenosisz kota", desc: "Delikatnie.", chance: 50, success: { media: 2, note: "zdj\u0119cie z kotem robi furor\u0119" }, fail: { wear: 1, note: "kot nie by\u0142 zachwycony" }, successText: "Kot mruczy ci w ramionach. Kto\u015B robi zdj\u0119cie, a profil klubu ma rekord polubie\u0144. Twoje zdj\u0119cia z walk maj\u0105 mniej.", failText: "Kot wyra\u017Anie nie zgadza si\u0119 z decyzj\u0105. Trzy zadrapania na przedramieniu wygl\u0105daj\u0105 gorzej ni\u017C po sparingu. Kot wraca na mat\u0119. Kot wygrywa przez TKO." }
    ]
  },
  {
    id: "reklama_pierogi",
    title: "Reklama pierogarni",
    weight: 3,
    cond: (s) => s.tier >= 1 && s.tier <= 3 && s.media >= 10,
    text: () => "Lokalna pierogarnia chce nakr\u0119ci\u0107 z tob\u0105 reklam\u0119: rozbijasz desk\u0119 r\u0119k\u0105, a z deski wypadaj\u0105 pierogi. Has\u0142o: \u201ESi\u0142a z ciasta\u201D. W\u0142a\u015Bcicielka chce, \u017Ceby\u015B \u201Erozbija\u0142 z mi\u0142o\u015Bci\u0105\u201D.",
    choices: (s) => [
      { label: "Kr\u0119cisz", desc: "Pieni\u0105dze i pierogi gratis do ko\u0144ca roku. I ksywka na ca\u0142e \u017Cycie.", effects: { money: cash(s, 0.03, 1500), media: 2, rep: -1, note: "koledzy wo\u0142aj\u0105 na ciebie \u201EPiero\u017Cek\u201D" } },
      { label: "Odmawiasz", desc: "Godno\u015B\u0107 ponad pierogi. Pierwszy raz w historii polskiego sportu.", effects: { rep: 1 } }
    ]
  },
  {
    id: "pomylka_hotel",
    title: "Pomy\u0142ka w hotelu",
    weight: 3,
    cond: (s) => s.tier >= 2,
    text: () => "Organizator gali zakwaterowa\u0142 ci\u0119 w jednym pokoju z rywalem z karty wst\u0119pnej. Dwa \u0142\xF3\u017Cka, jedna \u0142azienka, zero planu. Na drzwiach kartka: \u201EPanowie, oszcz\u0119dzamy, prosimy o wyrozumia\u0142o\u015B\u0107\u201D.",
    choices: () => [
      { label: "Zostajesz", desc: "Jak doro\u015Bli ludzie. Nawet je\u015Bli jeden z was za tydzie\u0144 z\u0142amie drugiemu nos.", chance: 60, success: { rep: 2, media: 1, note: "wsp\xF3lne zdj\u0119cie z rywalem obiega internet" }, fail: { form: -2, note: "rywal chrapie jak traktor" }, successText: "Wieczorem gracie razem w karty, rano robicie sobie zdj\u0119cie w szlafrokach z hotelowym logo. Kibice pisz\u0105, \u017Ce \u201Etak powinien wygl\u0105da\u0107 sport\u201D. Organizator pisze, \u017Ce szlafroki s\u0105 do zwrotu.", failText: "Rywal chrapie jak traktor w \u017Cniwa, a o trzeciej m\xF3wi przez sen: \u201ERozj***\u0119 go\u201D. Chyba o tobie. Zasypiasz o czwartej z poduszk\u0105 na g\u0142owie i no\u017Cem do mas\u0142a pod r\u0119k\u0105." },
      { label: "\u017B\u0105dasz innego pokoju", desc: "Organizator si\u0119 krzywi, ale dop\u0142aca za drugi pok\xF3j. Przypomni ci to przy nast\u0119pnej umowie.", effects: { form: 1, rep: -1 } }
    ]
  },
  {
    id: "ochroniarz_wejscie",
    title: "Ochroniarz ci\u0119 nie wpuszcza",
    weight: 3,
    cond: (s) => s.tier >= 1,
    text: () => "Federacja zaprasza ci\u0119 na gal\u0119, \u017Ceby\u015B pokaza\u0142 si\u0119 kibicom z klatki. Ochroniarz przy wej\u015Bciu dla zawodnik\xF3w nie wierzy, \u017Ce jeste\u015B na li\u015Bcie. \u201EKa\u017Cdy tak m\xF3wi, mistrzu. Bilet masz? Nie? To sp******aj, nie blokuj przej\u015Bcia\u201D.",
    choices: () => [
      { label: "Pokazujesz plakat na telefonie", desc: "Ochroniarz trzy razy por\xF3wnuje plakat z twoj\u0105 twarz\u0105, zanim ci\u0119 wpu\u015Bci.", effects: { media: 1, note: "ochroniarz prosi o autograf dla syna" } },
      { label: "Dzwonisz do organizatora", desc: "Dwadzie\u015Bcia minut czekania na zimnie. Organizator odbiera za sz\xF3stym razem: \u201EKto? Aaa, ty\u201D.", effects: { form: -1, rep: 2, note: "organizator przeprasza na scenie, sala bije brawo" } }
    ]
  },
  {
    id: "auto_cofka",
    title: "Spodenki w praniu",
    weight: 3,
    cond: (s) => s.tier >= 1,
    text: () => "Dwie godziny przed walk\u0105 okazuje si\u0119, \u017Ce spodenki walkowe zosta\u0142y w pralce. W hotelu. W innym mie\u015Bcie. W pralce, kt\xF3r\u0105 kto\u015B w mi\u0119dzyczasie w\u0142\u0105czy\u0142.",
    choices: () => [
      { label: "Po\u017Cyczasz od kolegi z klubu", desc: "Dwa rozmiary za du\u017Ce. Kolega m\xF3wi, \u017Ce \u201Esznurek trzyma\u201D. Sznurek nie trzyma.", effects: { media: 2, form: -1, note: "w klatce trzymasz spodenki jedn\u0105 r\u0119k\u0105" } },
      { label: "Kupujesz w sklepie przy hali", desc: "Jedyne, jakie maj\u0105: r\xF3\u017Cowe z jednoro\u017Ccem i brokatem. Sprzedawca m\xF3wi, \u017Ce \u201Eto model limitowany\u201D. Limitowany przez to, \u017Ce nikt go nie kupi\u0142.", effects: { media: 3, rep: 1, money: -350, note: "jednoro\u017Cec staje si\u0119 twoim znakiem (i kosztuje jak jednoro\u017Cec)" } }
    ]
  },
  {
    id: "wujek_rada",
    title: "Wujek ekspert",
    weight: 3,
    cond: (s) => s.age >= 17,
    text: () => "Na imieninach wujek, kt\xF3ry ostatni raz \u0107wiczy\u0142 w wojsku w 1989, t\u0142umaczy ci przy stole, jak \u201Epowiniene\u015B by\u0142\u201D wygra\u0107 ostatni\u0105 walk\u0119. Z rysunkami na serwetce i kie\u0142bas\u0105 zamiast wska\u017Anika.",
    choices: () => [
      { label: "S\u0142uchasz z u\u015Bmiechem", desc: "Rodzina jest najwa\u017Cniejsza. Wujek jest najg\u0142o\u015Bniejszy.", effects: { relations: 2, note: "wujek rozpowiada, \u017Ce to jego taktyka" } },
      { label: "Zapraszasz go na sparing", desc: "Lekki, techniczny. Wujek m\xF3wi, \u017Ce \u201Elekki to on nie umie\u201D.", chance: 85, success: { relations: -1, media: 2, note: "wujek przyznaje, \u017Ce to nie takie proste" }, fail: { relations: -3, note: "wujek obrazi\u0142 si\u0119 na ca\u0142\u0105 rodzin\u0119" }, successText: "Po trzydziestu sekundach wujek le\u017Cy na macie i m\xF3wi, \u017Ce \u201Ekolano mu si\u0119 odezwa\u0142o, to z wojska\u201D. Filmik ma tysi\u0105ce wy\u015Bwietle\u0144. Wujek m\xF3wi, \u017Ce by\u0142 ustawiony.", failText: "Wujek wychodzi z imienin, a ciocia przez telefon wyja\u015Bnia twojej mamie, \u017Ce \u201Esyn ma za du\u017Co w g\u0142owie, a za ma\u0142o szacunku\u201D. Rodzinny czat milknie na trzy tygodnie." }
    ]
  },
  {
    id: "kanapka_waga",
    title: "Kanapka na wadze",
    weight: 3,
    cond: (s) => s.tier >= 1,
    text: () => "Przy oficjalnym wa\u017Ceniu rywal wyjmuje z kieszeni kanapk\u0119 ze schabowym i je j\u0105 ci przed nosem, mlaszcz\u0105c do mikrofonu. Ty nie pi\u0142e\u015B wody od wczoraj. Tw\xF3j \u017Co\u0142\u0105dek wydaje d\u017Awi\u0119k, kt\xF3ry s\u0142yszy ca\u0142a sala.",
    choices: () => [
      { label: "Patrzysz mu w oczy", desc: "Kamie\u0144.", effects: { rep: 2, form: 1 } },
      { label: "Zabierasz mu kanapk\u0119", desc: "I zjadasz. Jak drapie\u017Cnik.", chance: 50, success: { media: 4, note: "klip roku" }, fail: { media: 2, rep: -2, form: -1, note: "kara od komisji i b\xF3l brzucha" }, successText: "Hala wybucha \u015Bmiechem, rywal stoi z pust\u0105 r\u0119k\u0105 i okruszkami na brodzie. Klip trafia do wszystkich podsumowa\u0144 tygodnia. MMAKlops: \u201ESCHABOWY NOKAUT!\u201D.", failText: "Komisja nie widzi w tym nic \u015Bmiesznego, a schabowy po dw\xF3ch dniach g\u0142od\xF3wki to by\u0142 z\u0142y pomys\u0142. P\xF3\u0142 nocy rozmawiasz z muszl\u0105 klozetow\u0105." }
    ]
  },
  {
    id: "fan_tatuaz",
    title: "Mural fana",
    once: true,
    weight: 3,
    cond: (s) => s.media >= 30,
    text: () => "Fan wrzuca zdj\u0119cie: namalowa\u0142 sprayem twoj\u0105 twarz na \u015Bcianie gara\u017Cu, trzy metry na dwa. Podobie\u0144stwo jest\u2026 umowne. Bardziej przypominasz na nim ziemniaka w r\u0119kawicach, kt\xF3ry dosta\u0142 udaru. Sp\xF3\u0142dzielnia ju\u017C pisze pismo.",
    choices: () => [
      { label: "Udost\u0119pniasz z sercem", desc: "Szacunek dla oddania. I dla odwagi malarza.", effects: { media: 3, rep: 1, note: "fan zostaje lokaln\u0105 gwiazd\u0105" } },
      { label: "Fundujesz mu poprawk\u0119", desc: "U prawdziwego grafficiarza, kt\xF3ry patrzy na \u015Bcian\u0119 i m\xF3wi \u201Ek***a, ale co tu si\u0119 sta\u0142o?\u201D.", effects: { money: -800, media: 4, rep: 2, note: "ziemniak zamienia si\u0119 w ciebie" } }
    ]
  },
  {
    id: "komentator_myli",
    title: "Komentator myli nazwisko",
    weight: 3,
    cond: (s) => s.tier >= 2,
    text: (s) => `Przez ca\u0142\u0105 transmisj\u0119 komentator nazywa ci\u0119 \u201E${s.profile.lastName.slice(0, -1)}${s.profile.lastName.endsWith("a") ? "o" : "a"}\u201D. Raz nawet \u201Etym drugim\u201D. Internet podchwytuje to szybciej, ni\u017C ty wstajesz z maty.`,
    choices: () => [
      { label: "Przyjmujesz now\u0105 ksywk\u0119", desc: "Skoro tak m\xF3wi\u0105. Skoro nawet mama tak m\xF3wi.", effects: { media: 3, note: "kibice skanduj\u0105 przekr\u0119cone nazwisko" } },
      { label: "Prostujesz w wywiadzie", desc: "Z u\u015Bmiechem. Dziennikarz i tak przekr\u0119ca.", effects: { rep: 1, media: 1 } }
    ]
  },
  {
    id: "reklama_bank",
    title: "Klient banku",
    weight: 2,
    cond: (s) => s.tier >= 2 && s.money >= 5e4,
    text: () => "Doradca w banku, widz\u0105c saldo, nagle przestaje ci\u0119 nazywa\u0107 \u201Epanem klientem\u201D i zaczyna \u201Epanem mistrzem\u201D. Proponuje \u201Eprodukt inwestycyjny dla sportowc\xF3w\u201D: fundusz oparty na cenach karmy dla ps\xF3w.",
    choices: (s) => [
      { label: "Wchodzisz w to", desc: "Psy zawsze b\u0119d\u0105 je\u015B\u0107. Ty nie zawsze, ale psy tak.", chance: 45, success: { money: cash(s, 0.06, 4e3), note: "karma dla ps\xF3w idzie w g\xF3r\u0119" }, fail: { money: -cash(s, 0.05, 3e3), note: "kryzys na rynku karmy" }, successText: "Po p\xF3\u0142 roku dostajesz list z banku. Wszystko w g\xF3r\u0119. Doradca pisze, \u017Ce \u201Ezawsze wierzy\u0142 w psy\u201D. I w prowizj\u0119.", failText: "Wielka sie\u0107 sklep\xF3w wprowadza w\u0142asn\u0105 karm\u0119 i fundusz leci w d\xF3\u0142. Doradca jest na urlopie. Potem na L4. Potem w innym banku." },
      { label: "Dzi\u0119kujesz", desc: "Pieni\u0105dze lubi\u0105 spok\xF3j. Doradca nie lubi spokoju, bo nie ma prowizji.", effects: { note: "doradca wysy\u0142a ci kalendarz z psami" } }
    ]
  },
  {
    id: "dziecko_autograf",
    title: "Ma\u0142y kibic",
    weight: 3,
    cond: (s) => s.tier >= 1 && s.media >= 15,
    text: () => "Po treningu czeka na ciebie ch\u0142opiec z mam\u0105. Pokazuje ci sw\xF3j rysunek: ty w klatce, z pasem, a obok smok. \u201ESmok to tw\xF3j trener\u201D. Bardzo dobrze uchwycony.",
    choices: () => [
      { label: "Zapraszasz go na trening", desc: "Niech pozna smoka osobi\u015Bcie. Smok mi\u0119knie na widok dzieci.", effects: { rep: 3, relations: 1, form: -1, note: "trener zaczyna m\xF3wi\u0107 o sobie \u201Esmok\u201D" } },
      { label: "Podpisujesz rysunek", desc: "I robicie zdj\u0119cie. Mama ch\u0142opca te\u017C chce zdj\u0119cie. Z trenerem. Smokiem.", effects: { rep: 1, media: 1 } }
    ]
  },
  {
    id: "sponsor_gadzet",
    title: "Gad\u017Cet od sponsora",
    weight: 3,
    cond: (s) => s.sponsors.length >= 2,
    text: () => "Sponsor przysy\u0142a elektryczny pas na brzuch, kt\xF3ry \u201Ezast\u0119puje 300 brzuszk\xF3w\u201D. Po polsku w instrukcji jedno zdanie: \u201ENie u\u017Cywa\u0107 w wannie\u201D. Reszta w obcym alfabecie, z rysunkiem cz\u0142owieka w ogniu.",
    choices: () => [
      { label: "Testujesz na nagraniu", desc: "Dla sponsora. I dla nauki.", chance: 60, success: { media: 2, note: "sponsor zachwycony recenzj\u0105" }, fail: { wear: 1, media: 2, note: "pas kopie mocniej ni\u017C rywale" }, successText: "Robisz powa\u017Cn\u0105 min\u0119, pas buczy. Brzuch nic nie czuje, ale min\u0119 masz profesjonaln\u0105. Sponsor zamawia od razu drugi film.", failText: "Pas uruchamia si\u0119 na maksymalnej mocy. Tw\xF3j krzyk s\u0142ycha\u0107 na s\u0105siedniej ulicy, a nagranie ma setki tysi\u0119cy wy\u015Bwietle\u0144 z tytu\u0142em \u201EMISTRZ VS PAS: PAS WYGRYWA PRZEZ PODDANIE\u201D." },
      { label: "Oddajesz bratu", desc: "Niech on si\u0119 m\u0119czy. Brat zak\u0142ada go na kota.", effects: { relations: 1 } }
    ]
  },
  {
    id: "rap_wejscie",
    title: "Piosenka na wej\u015Bcie",
    weight: 3,
    cond: (s) => s.tier >= 1,
    text: (s) => vary3(s, [
      "Kuzyn nagra\u0142 dla ciebie piosenk\u0119 na wej\u015Bcie. Disco polo o tym, jak \u201Ezgasisz \u015Bwiat\u0142o ka\u017Cdemu rywalowi, oj dana, dana\u201D. Refren wpada w ucho. I ju\u017C nie wypada.",
      "Lokalny raper \u201EMC Blokers\u201D proponuje numer na twoje wej\u015Bcie. Rymuje twoje nazwisko z \u201Ekombajn\u201D. Pytany dlaczego, m\xF3wi: \u201EFlow, ziomek. Flow\u201D."
    ]),
    choices: () => [
      { label: "Wchodzisz przy tym", desc: "Hala to pokocha. Albo ci\u0119 znienawidzi. W disco polo nie ma \u015Brodka.", chance: 55, success: { media: 3, relations: 1, note: "ca\u0142a hala \u015Bpiewa refren" }, fail: { rep: -2, media: 2, note: "hala w ciszy, rywal si\u0119 \u015Bmieje" }, successText: "Przy drugim refrenie \u015Bpiewa ca\u0142a hala, ochroniarze te\u017C. Nast\u0119pnego dnia piosenka leci w lokalnym radiu, mi\u0119dzy prognoz\u0105 pogody a nekrologami.", failText: "Cisz\u0119 przerywa tylko tw\xF3j kuzyn, \u015Bpiewaj\u0105cy z pierwszego rz\u0119du, i jego dziewczyna nagrywaj\u0105ca to w pionie. Rywal na face to face nie mo\u017Ce powstrzyma\u0107 u\u015Bmiechu. Ty te\u017C nie, ale z innego powodu." },
      { label: "Zostajesz przy klasyku", desc: "Sprawdzony numer. Nikt nie za\u015Bpiewa, ale te\u017C nikt si\u0119 nie za\u015Bmieje.", effects: { form: 1 } }
    ]
  }
];

// src/engine/events_rep.ts
