// src/engine/people.ts
var roczFlag = (s) => `rocz${s.season}`;
function partnerK(s) {
  const k = (s.season + s.history.length) % 4;
  return k === 0 && s.flags[roczFlag(s)] ? 1 : k;
}
var sc3 = (s) => [1, 1.5, 3, 5, 8][Math.min(4, Math.max(0, s.tier))] ?? 1;
var zl6 = (s, n) => Math.max(50, Math.round(n * sc3(s) / 50) * 50);
var cena3 = (_s, n) => Math.max(10, Math.round(n / 10) * 10);
var clamp4 = (v, a, b) => Math.max(a, Math.min(b, v));
var PARTNERS = ["Ola", "Kasia", "Wiktoria", "Julia", "Martyna", "Paulina"];
var kumpelName = (s) => s.profile.firstName === "Kamil" ? "Kuba" : "Kamil";
function ensurePeople(s) {
  if (!s.people) s.people = { mama: 60, kumpel: 55, partner: null };
  return s.people;
}
function partnerName(s) {
  return s.people?.partner?.name ?? "Ola";
}
function applyBond(s, b) {
  const p = ensurePeople(s);
  if (b.mama) p.mama = clamp4(p.mama + b.mama, 0, 100);
  if (b.kumpel) p.kumpel = clamp4(p.kumpel + b.kumpel, 0, 100);
  if (b.partner === 999) {
    const name = PARTNERS[(s.season * 7 + s.profile.lastName.length) % PARTNERS.length];
    p.partner = { name, bond: 55, since: s.season };
  } else if (b.partner && p.partner) p.partner.bond = clamp4(p.partner.bond + b.partner, 0, 100);
}
function peopleYear(rng, s) {
  const p = ensurePeople(s);
  const out = [];
  p.mama = clamp4(p.mama - 4, 0, 100);
  p.kumpel = clamp4(p.kumpel - 5, 0, 100);
  if (p.partner) {
    p.partner.bond = clamp4(p.partner.bond - 6, 0, 100);
    if (p.partner.bond < 25) {
      out.push(`${p.partner.name} pakuje rzeczy. \u201ETy masz klatk\u0119, ja chc\u0119 mie\u0107 kogo\u015B. Ekspres do kawy zabieram\u201D. Forma w nowym roku \u22122.`);
      s.flags.formBonus = (s.flags.formBonus ?? 0) - 2;
      s.relations -= 1;
      p.exes = (p.exes ?? 0) + 1;
      p.partner = null;
    } else if (p.partner.bond >= 70) {
      out.push(`W domu spok\xF3j: ${p.partner.name} czeka po ka\u017Cdym treningu i nawet nie komentuje zapachu. Forma w nowym roku +1.`);
      s.flags.formBonus = (s.flags.formBonus ?? 0) + 1;
    }
  }
  if (p.mama >= 80) {
    s.relations += 1;
    out.push("Mama chwali si\u0119 tob\u0105 ca\u0142ej parafii, tak\u017Ce w trakcie kazania. Rodzina +1.");
  } else if (p.mama < 20) {
    s.relations -= 1;
    out.push("Mama m\xF3wi s\u0105siadkom, \u017Ce \u201Esyn ma teraz wa\u017Cniejsze sprawy\u201D. M\xF3wi to tak, \u017Ceby\u015B si\u0119 dowiedzia\u0142. Rodzina \u22121.");
  }
  if (p.kumpel >= 80) {
    s.media = clamp4(s.media + 1, 0, 100);
    out.push(`${kumpelName(s)} z osiedla robi ci darmowy PR: p\xF3\u0142 dzielnicy ma twoje zdj\u0119cie w telefonie, druga po\u0142owa ma je na tapecie. Media +1.`);
  } else if (p.kumpel < 20) {
    s.rep = clamp4(s.rep - 1, 0, 100);
    out.push(`${kumpelName(s)} pisze na Boomerbooku, \u017Ce \u201Ewoda sodowa uderzy\u0142a ci do g\u0142owy, a kiedy\u015B to by\u0142 normalny ch\u0142op\u201D. 40 os\xF3b z osiedla daje \u0142apk\u0119. Reputacja \u22121.`);
  }
  void rng;
  return out;
}
